(function () {
  function periksa() {
    if (window.MYBIPA_SIAP === true) return;
    var k = document.getElementById("awas-berkas");
    if (k) k.hidden = false;
  }
  var t = document.getElementById("awas-tutup");
  if (t) t.addEventListener("click", function () {
    document.getElementById("awas-berkas").hidden = true;
  });
  if (document.readyState === "complete") setTimeout(periksa, 1200);
  else window.addEventListener("load", function () { setTimeout(periksa, 1200); });
})();


