/* Pembuka gerbang mandiri. Sengaja dipisah dari mesin utama agar tombol masuk
   tetap berfungsi walaupun ada bagian lain yang gagal dimuat. */
(function () {
  function siap(fn) {
    if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", fn);
    else fn();
  }
  siap(function () {
    var g = document.getElementById("gerbang");
    if (!g) return;
    function buka() {
      g.classList.add("buka");
      g.setAttribute("aria-hidden", "false");
      document.body.style.overflow = "hidden";
    }
    window.MYBIPA_BUKA_GERBANG = buka;
    document.addEventListener("click", function (ev) {
      var t = ev.target.closest ? ev.target.closest("#btn-akun, #btn-akun-bilah, #btn-mulai") : null;
      if (!t) return;
      if (document.body.dataset.masuk === "ya") return;   /* sudah masuk akun */
      setTimeout(function () { if (!g.classList.contains("buka")) buka(); }, 60);
    }, true);
  });
})();


