  /* ---------- Pengurai Tautan Daring (Google Drive & YouTube) ---------- */
  function ekstrakGoogleDriveId(url) {
    if (!url || typeof url !== "string") return null;
    var u = url.trim();
    var m = u.match(/\/file\/d\/([a-zA-Z0-9_-]+)/i) ||
            u.match(/[?&]id=([a-zA-Z0-9_-]+)/i) ||
            u.match(/\/d\/([a-zA-Z0-9_-]+)/i);
    return m ? m[1] : null;
  }

  function ekstrakYouTubeId(url) {
    if (!url || typeof url !== "string") return null;
    var u = url.trim();
    var ytMatch = u.match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?(?:.*&)?v=|embed\/|v\/|shorts\/))([\w-]{11})/i);
    return (ytMatch && ytMatch[1]) ? ytMatch[1] : null;
  }

  /* Mengubah URL (termasuk link Google Drive) menjadi URL gambar langsung untuk tag <img> */
  function ubahKeUrlGambar(url) {
    if (!url || typeof url !== "string") return "";
    var u = url.trim();
    var gdId = ekstrakGoogleDriveId(u);
    if (gdId) {
      /* lh3.googleusercontent.com/d/ID adalah endpoint resmi Google yang melayani gambar tanpa blokir */
      return "https://lh3.googleusercontent.com/d/" + gdId;
    }
    return u;
  }

  /* Memasang gambar dengan penanganan tautan daring Google Drive & fallback otomatis */
  function pasangGambarAman(elImg, urlAsli, fallbackUrl) {
    if (!elImg) return;
    if (!urlAsli) {
      if (fallbackUrl) { elImg.src = fallbackUrl; elImg.hidden = false; }
      else { elImg.src = ""; elImg.hidden = true; }
      return;
    }
    var urlOlahan = ubahKeUrlGambar(urlAsli);
    elImg.src = urlOlahan;
    elImg.hidden = false;

    var gdId = ekstrakGoogleDriveId(urlAsli);
    if (gdId) {
      elImg.onerror = function () {
        /* Jika endpoint lh3 dibatasi, coba thumbnail Google Drive */
        if (elImg.src && elImg.src.indexOf("lh3.googleusercontent.com") !== -1) {
          elImg.src = "https://drive.google.com/thumbnail?id=" + gdId + "&sz=w1600";
        } else if (fallbackUrl && elImg.src !== fallbackUrl) {
          elImg.src = fallbackUrl;
        }
      };
    } else {
      elImg.onerror = function () {
        if (fallbackUrl && elImg.src !== fallbackUrl) {
          elImg.src = fallbackUrl;
        }
      };
    }
  }

  /* Periksa apakah URL adalah tautan YouTube atau Google Drive untuk Audio & Video */
  function periksaVideoEmbed(url) {
    if (!url || typeof url !== "string") return null;
    var u = url.trim();
    var ytId = ekstrakYouTubeId(u);
    if (ytId) {
      return {
        tipe: "youtube",
        id: ytId,
        src: "https://www.youtube-nocookie.com/embed/" + ytId + "?rel=0"
      };
    }
    var gdId = ekstrakGoogleDriveId(u);
    if (gdId) {
      return {
        tipe: "drive",
        id: gdId,
        src: "https://drive.google.com/file/d/" + gdId + "/preview",
        directUrl: "https://drive.google.com/uc?export=download&id=" + gdId
      };
    }
    return null;
  }

  var DAFTAR_PEMASANG_MEDIA = [];
  function daftarkanPemasangMedia(kode, fn) {
    DAFTAR_PEMASANG_MEDIA.push({ kode: kode, fn: fn });
    if (MEDIA_KUSTOM && MEDIA_KUSTOM[kode]) {
      try { fn(MEDIA_KUSTOM[kode]); } catch (e) { }
    }
  }
  function terapkanSemuaMedia() {
    DAFTAR_PEMASANG_MEDIA.forEach(function (p) {
      try { if (MEDIA_KUSTOM[p.kode]) p.fn(MEDIA_KUSTOM[p.kode]); } catch (e) { }
    });
    var vm = document.getElementById("video-mars");
    if (MEDIA_KUSTOM["mars"] && vm) {
      vm.src = MEDIA_KUSTOM["mars"];
    }
  }

  /* Simpan foto ke Supabase TANPA local storage */
  function simpanFotoModul(selesai) {
    SUNTINGAN.__FOTO__ = FOTO_MODUL;
    simpanSuntingan();
    supabaseSimpanSuntinganSegera(function (ok, err) {
      if (selesai) selesai(ok, err);
    });
  }

  /* Simpan media ke Supabase TANPA local storage */
  function simpanMediaKustom(selesai) {
    SUNTINGAN.__MEDIA__ = MEDIA_KUSTOM;
    simpanSuntingan();
    supabaseSimpanSuntinganSegera(function (ok, err) {
      if (selesai) selesai(ok, err);
    });
  }
  function kecilkanGambar(berkas, sisiMaks, lanjut) {
    var pembaca = new FileReader();
    pembaca.onload = function () {
      var sumber = pembaca.result, sudah = false;
      function sekali(h) { if (sudah) return; sudah = true; lanjut(h); }
      setTimeout(function () { sekali(sumber); }, 1800);
      var gbr = new Image();
      gbr.onload = function () {
        try {
          var skala = Math.min(1, sisiMaks / Math.max(gbr.width, gbr.height));
          var kanvas = document.createElement("canvas");
          kanvas.width = Math.round(gbr.width * skala);
          kanvas.height = Math.round(gbr.height * skala);
          kanvas.getContext("2d").drawImage(gbr, 0, 0, kanvas.width, kanvas.height);
          sekali(kanvas.toDataURL("image/jpeg", 0.78));
        } catch (e) { sekali(sumber); }
      };
      gbr.onerror = function () { sekali(sumber); };
      gbr.src = sumber;
    };
    pembaca.readAsDataURL(berkas);
  }

  var KUNCI_NILAI = KUNCI_SIMPAN + "-nilai";
  var SKOR = bacaGudang(KUNCI_NILAI, {});      /* kunci butir -> 0..1 */
  var BUTIR_NILAI = {};                         /* hal -> {kunci: kemahiran} */
  var BAGIAN_KINI = "";
  var BOBOT_KEMAHIRAN = { menyimak: 30, berbicara: 30, membaca: 20, menulis: 20 };
  var NAMA_KEMAHIRAN = {
    menyimak: "Menyimak", berbicara: "Berbicara",
    membaca: "Membaca", menulis: "Menulis"
  };

  function petaKemahiran(nama) {
    if (/Menyimak/i.test(nama)) return "menyimak";
    if (/Berbicara/i.test(nama)) return "berbicara";
    if (/Membaca|Prakegiatan|Kosakata/i.test(nama)) return "membaca";
    return "menulis";
  }
  function daftarNilai(hal, kunci) {
    if (!BUTIR_NILAI[hal]) BUTIR_NILAI[hal] = {};
    BUTIR_NILAI[hal][kunci] = petaKemahiran(BAGIAN_KINI);
  }
  function simpanNilai() { tulisGudang(KUNCI_NILAI, SKOR); }
  function setNilai(hal, kunci, nilai) {
    SKOR[kunci] = nilai;
    simpanNilai();
    perbaruiNilaiUnit(hal);
    if (typeof perbaruiKunciUnit === "function") perbaruiKunciUnit();
    simpanRekap();
  }
  function nilaiUnit(hal) {
    var butir = BUTIR_NILAI[hal] || {};
    var ember = {}, adaButir = 0, terjawab = 0;
    Object.keys(butir).forEach(function (k) {
      var m = butir[k];
      if (!ember[m]) ember[m] = { jumlah: 0, nilai: 0, terjawab: 0 };
      ember[m].jumlah++; adaButir++;
      if (SKOR[k] !== undefined) { ember[m].nilai += SKOR[k]; ember[m].terjawab++; terjawab++; }
    });
    var totalBobot = 0, angka = 0, rinci = {};
    Object.keys(ember).forEach(function (m) {
      if (!ember[m].jumlah) return;
      var rata = ember[m].nilai / ember[m].jumlah * 100;
      rinci[m] = { nilai: Math.round(rata), jumlah: ember[m].jumlah, terjawab: ember[m].terjawab };
      var bobot = BOBOT_KEMAHIRAN[m] || 0;
      totalBobot += bobot; angka += rata * bobot;
    });
    var p = POIN[hal] || { total: 0, selesai: {} };
    var selesaiKegiatan = Object.keys(p.selesai).length;
    return {
      nilai: totalBobot ? Math.round(angka / totalBobot) : 0,
      rinci: rinci, butir: adaButir, terjawab: terjawab,
      kegiatanTotal: p.total, kegiatanSelesai: selesaiKegiatan,
      tuntas: p.total > 0 && selesaiKegiatan >= p.total && terjawab >= adaButir && adaButir > 0
    };
  }
  function predikatNilai(x) {
    if (x >= 81) return "Sangat Baik";
    if (x >= 71) return "Baik";
    if (x >= 60) return "Cukup";
    return "Belum Memenuhi";
  }
  function rekapSemuaUnit() {
    var daftar = [], jumlah = 0, tuntas = 0;
    UNIT.forEach(function (u) {
      var r = nilaiUnit("unit-" + u.no);
      if (NILAI_TIMPA[u.no] !== undefined && NILAI_TIMPA[u.no] !== "") {
        r.nilai = parseInt(NILAI_TIMPA[u.no], 10) || 0;
        r.timpa = true;
      }
      daftar.push({ no: u.no, judul: u.judul, hasil: r });
      if (r.tuntas || r.timpa) { jumlah += r.nilai; tuntas++; }
    });
    return {
      daftar: daftar, tuntas: tuntas, total: UNIT.length,
      rata: tuntas ? Math.round(jumlah / tuntas) : 0,
      lengkap: tuntas >= UNIT.length
    };
  }
  var KUNCI_TIMPA = KUNCI_SIMPAN + "-timpa";
  var NILAI_TIMPA = bacaGudang(KUNCI_TIMPA, {});
  function simpanTimpa() { tulisGudang(KUNCI_TIMPA, NILAI_TIMPA); }

  /* Pembaca jawaban skrip lewat jalur JSONP. Peramban membatasi pembacaan jawaban
     lintas alamat, tetapi tidak membatasi pemuatan berkas program. Jalur ini
     memanfaatkannya, sehingga jawaban Apps Script selalu dapat dibaca. */
  var NOMOR_JSONP = 0;
  function bacaBasisData(parameter, lanjut) {
    if (!URL_SINKRON) { lanjut(null); return; }
    parameter = parameter || {};
    if (!parameter.tingkat) parameter.tingkat = TINGKAT_MODUL;
    var nama = "mybipaJawab" + (++NOMOR_JSONP) + "_" + Date.now();
    var skrip = document.createElement("script");
    var selesai = false;
    var waktu = setTimeout(function () { tutup(null); }, 12000);
    function tutup(hasil) {
      if (selesai) return;
      selesai = true;
      clearTimeout(waktu);
      try { delete window[nama]; } catch (e) { window[nama] = undefined; }
      if (skrip.parentNode) skrip.parentNode.removeChild(skrip);
      lanjut(hasil);
    }
    window[nama] = function (jawab) { tutup(jawab); };
    var bagian = [];
    Object.keys(parameter || {}).forEach(function (k) {
      bagian.push(encodeURIComponent(k) + "=" + encodeURIComponent(parameter[k]));
    });
    bagian.push("callback=" + nama);
    skrip.src = URL_SINKRON + "?" + bagian.join("&");
    skrip.onerror = function () { tutup(null); };
    document.head.appendChild(skrip);
  }

  var SINKRON_TERAKHIR = 0;
  var SINKRON_TUNTAS = -1;
  function kirimSinkron(muatan, lanjut) {
    if (!URL_SINKRON) return;
    var sudah = false;
    function cadangan() {
      if (sudah) return;
      sudah = true;
      /* jalur cadangan: dikirim sebagai permintaan biasa sehingga tidak terhalang peramban */
      bacaBasisData({ aksi: "simpan", data: JSON.stringify(muatan) }, function (j) {
        if (lanjut) lanjut(!!(j && j.ok));
      });
    }
    try {
      fetch(URL_SINKRON, {
        method: "POST", mode: "no-cors",
        headers: { "Content-Type": "text/plain;charset=utf-8" },
        body: JSON.stringify(muatan)
      }).then(function () { sudah = true; if (lanjut) lanjut(true); })
        .catch(cadangan);
    } catch (e) { cadangan(); }
  }

  function simpanRekap() {
    if (!AKUN) return;
    var r = rekapSemuaUnit();
    var semua = bacaGudang(KUNCI_REKAP, {});
    semua[AKUN.surel] = {
      nama: AKUN.nama, instansi: AKUN.instansi, surel: AKUN.surel, wa: AKUN.wa,
      unit: r.daftar.map(function (d) { return d.hasil.tuntas || d.hasil.timpa ? d.hasil.nilai : null; }),
      tuntas: r.tuntas, rata: r.rata, lengkap: r.lengkap,
      diperbarui: new Date().toISOString()
    };
    tulisGudang(KUNCI_REKAP, semua);

    /* kirim ke spreadsheet paling sering satu kali tiap sepuluh detik */
    var sekarang = Date.now();
    var isiKini = semua[AKUN.surel];
    var berubahTuntas = SINKRON_TUNTAS !== isiKini.tuntas;
    if (URL_SINKRON && (berubahTuntas || sekarang - SINKRON_TERAKHIR > 10000)) {
      if (SINKRON_TUNTAS >= 0 && berubahTuntas) {
        catatKegiatan("unit tuntas", "jumlah unit tuntas " + isiKini.tuntas + ", nilai " + isiKini.rata);
      }
      SINKRON_TUNTAS = isiKini.tuntas;
      SINKRON_TERAKHIR = sekarang;
      var isi = semua[AKUN.surel];
      kirimSinkron({
        aksi: "simpan", nama: AKUN.nama, surel: AKUN.surel, wa: AKUN.wa,
        instansi: AKUN.instansi, peran: AKUN.peran,
        dosen: AKUN.dosen || "", catatan: "kemajuan", tingkat: TINGKAT_MODUL,
        sandi: AKUN.sandi || "",
        unit: isi.unit, tuntas: isi.tuntas, rata: isi.rata, lengkap: isi.lengkap,
        penuh: { tingkat: TINGKAT_MODUL, jawaban: JAWAB, nilai: SKOR, timpa: NILAI_TIMPA }
      });
    }
  }

  function perbaruiNilaiUnit(hal) {
    var kotak = document.querySelector('.nilai-unit[data-hal="' + hal + '"]');
    if (!kotak) return;
    var r = nilaiUnit(hal);
    var angka = kotak.querySelector(".nu-angka");
    var cap = kotak.querySelector(".nu-cap");
    var ket = kotak.querySelector(".nu-ket");
    var rinci = kotak.querySelector(".nu-rinci");
    kotak.classList.toggle("tuntas", r.tuntas);
    if (r.tuntas) {
      angka.textContent = r.nilai;
      cap.textContent = predikatNilai(r.nilai);
      cap.className = "nu-cap" + (r.nilai < 60 ? " kurang" : "");
      ket.textContent = "Seluruh kegiatan unit ini sudah Anda kerjakan.";
    } else {
      angka.textContent = "\u2013";
      cap.textContent = "Belum lengkap";
      cap.className = "nu-cap tunggu";
      ket.textContent = "Nilai muncul setelah seluruh kegiatan unit ini terisi. Sudah " +
        r.kegiatanSelesai + " dari " + r.kegiatanTotal + " kegiatan.";
    }
    var potong = [];
    Object.keys(r.rinci).forEach(function (m) {
      potong.push("<span>" + NAMA_KEMAHIRAN[m] + " " +
        (r.rinci[m].terjawab >= r.rinci[m].jumlah ? r.rinci[m].nilai : "\u2013") +
        " <i>" + (BOBOT_KEMAHIRAN[m] || 0) + "%</i></span>");
    });
    rinci.innerHTML = potong.join("");
    var lencana = document.querySelector('.lencana[data-hal="' + hal + '"]');
    if (lencana) lencana.classList.toggle("tampil", r.tuntas);
    bukaTombolKunci(hal, r.tuntas);
  }
  function unitTerbuka(no) {
    if (no <= 1) return true;
    if (PENGELOLA) return true;
    var sebelum = nilaiUnit("unit-" + (no - 1));
    if (sebelum.tuntas) return true;
    if (NILAI_TIMPA[no - 1] !== undefined && NILAI_TIMPA[no - 1] !== "") return true;
    return false;
  }
  function perbaruiKunciUnit() {
    UNIT.forEach(function (u) {
      var buka = unitTerbuka(u.no);
      var lembar = document.getElementById("unit-" + u.no);
      if (lembar) {
        var gembok = lembar.querySelector(".gembok-unit");
        if (gembok) gembok.style.display = buka ? "none" : "";
        Array.prototype.forEach.call(lembar.children, function (el) {
          if (el.classList.contains("gembok-unit")) return;
          if (el.classList.contains("batas") && el === lembar.firstChild) return;
          el.style.display = buka ? "" : "none";
        });
        var batasAwal = lembar.querySelector(".batas");
        if (batasAwal) batasAwal.style.display = "";
      }
      var tautan = document.querySelector('#daftar-unit a[href="#unit-' + u.no + '"]');
      if (tautan) tautan.classList.toggle("terkunci", !buka);
    });
  }

  function perbaruiSemuaNilai() {
    UNIT.forEach(function (u) { perbaruiNilaiUnit("unit-" + u.no); });
    perbaruiKunciUnit();
    simpanRekap();
    if (typeof segarkanSertifikat === "function") segarkanSertifikat();
  }

  var TOMBOL_KUNCI = {};
  function daftarTombolKunci(hal, tombol) {
    if (!TOMBOL_KUNCI[hal]) TOMBOL_KUNCI[hal] = [];
    TOMBOL_KUNCI[hal].push(tombol);
    tombol.disabled = true;
    tombol.classList.add("terkunci");
    tombol.title = "Terbuka setelah seluruh kegiatan unit ini selesai dan nilai unit keluar.";
  }
  function bukaTombolKunci(hal, boleh) {
    (TOMBOL_KUNCI[hal] || []).forEach(function (t) {
      t.disabled = !boleh;
      t.classList.toggle("terkunci", !boleh);
      t.title = boleh ? "Menampilkan kunci tidak lagi mengubah nilai unit Anda."
        : "Terbuka setelah seluruh kegiatan unit ini selesai dan nilai unit keluar.";
    });
  }

  function daftarPoin(hal, kunci) {
    if (!POIN[hal]) POIN[hal] = { total: 0, selesai: {} };
    POIN[hal].total++;
    if (JAWAB[kunci] !== undefined && JAWAB[kunci] !== "") POIN[hal].selesai[kunci] = true;
  }
  function tandaiPoin(hal, kunci) {
    if (!POIN[hal]) POIN[hal] = { total: 0, selesai: {} };
    POIN[hal].selesai[kunci] = true;
    perbaruiLaju();
  }
  function perbaruiLaju() {
    var total = 0, selesai = 0;
    Object.keys(POIN).forEach(function (h) {
      total += POIN[h].total;
      selesai += Object.keys(POIN[h].selesai).length;
      var tautan = document.querySelector('a[data-hal="' + h + '"]');
      if (tautan) {
        var p = POIN[h].total ? Object.keys(POIN[h].selesai).length / POIN[h].total : 0;
        tautan.classList.toggle("tuntas", p >= 0.8);
      }
      var lencana = document.querySelector('.lencana[data-hal="' + h + '"]');
      if (lencana) {
        var q = POIN[h].total ? Object.keys(POIN[h].selesai).length / POIN[h].total : 0;
        lencana.classList.toggle("tampil", q >= 0.8);
      }
    });
    var persen = total ? Math.round(selesai / total * 100) : 0;
    var bar = document.getElementById("laju-bar");
    if (bar) bar.style.width = persen + "%";
    var teks = document.getElementById("laju-teks");
    if (teks) teks.textContent = persen + "% · " + selesai + " dari " + total + " butir kegiatan";
    if (typeof perbaruiSemuaNilai === "function" && SIAP_NILAI) perbaruiSemuaNilai();
  }
  var SIAP_NILAI = false;

  /* ---------- Pembangun Pemutar Audio Mewah Berbalut Emas Minangkabau ---------- */
  function bangunPemutarAudioKustom(wadahPemutar) {
    var bungkus = E("div", "pemutar-kustom");
    var audio = document.createElement("audio");
    audio.className = "audio-inti";
    audio.preload = "metadata";
    bungkus.appendChild(audio);

    var baris = E("div", "pemutar-baris-utama");

    // 1. Tombol Putar / Jeda
    var btnPlay = E("button", "tbl-putar");
    btnPlay.type = "button";
    btnPlay.setAttribute("aria-label", "Putar audio");
    btnPlay.innerHTML = '<svg class="ikon-play" viewBox="0 0 24 24"><polygon points="7,5 19,12 7,19"/></svg>' +
      '<svg class="ikon-pause" viewBox="0 0 24 24"><rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/></svg>';

    // 2. Tombol Lompat -5s & +5s
    var btnMundur = E("button", "tbl-lompat mundur");
    btnMundur.type = "button";
    btnMundur.title = "Mundur 5 detik";
    btnMundur.innerHTML = '<svg viewBox="0 0 24 24"><path d="M12.5 8c-2.65 0-5.05 1-6.9 2.6L2 7v9h9l-3.62-3.62c1.39-1.2 3.16-1.98 5.12-1.98 3.89 0 7.14 2.78 7.82 6.43l2.43-.5C21.84 12.16 17.65 8 12.5 8z" fill="currentColor"/><text x="12" y="16" font-size="7" font-weight="bold" text-anchor="middle" fill="currentColor">5</text></svg>';

    var btnMaju = E("button", "tbl-lompat maju");
    btnMaju.type = "button";
    btnMaju.title = "Maju 5 detik";
    btnMaju.innerHTML = '<svg viewBox="0 0 24 24"><path d="M11.5 8c2.65 0 5.05 1 6.9 2.6L22 7v9h-9l3.62-3.62c-1.39-1.2-3.16-1.98-5.12-1.98-3.89 0-7.14 2.78-7.82 6.43l-2.43-.5C2.16 12.16 6.35 8 11.5 8z" fill="currentColor"/><text x="12" y="16" font-size="7" font-weight="bold" text-anchor="middle" fill="currentColor">5</text></svg>';

    // 3. Linimasa Waktu & Rel Kemajuan
    var linimasa = E("div", "pemutar-linimasa");
    var relWaktu = E("div", "pemutar-rel-waktu");
    var teksKini = E("span", "waktu-kini", "00:00");
    var rel = E("div", "rel-kemajuan");
    var relIsi = E("div", "rel-isi");
    var relPegangan = E("div", "rel-pegangan");
    relIsi.appendChild(relPegangan);
    rel.appendChild(relIsi);
    var teksTotal = E("span", "waktu-total", "00:00");

    relWaktu.appendChild(teksKini);
    relWaktu.appendChild(rel);
    relWaktu.appendChild(teksTotal);
    linimasa.appendChild(relWaktu);

    // 4. Tombol Kecepatan
    var daftarKec = [1, 1.25, 1.5, 0.75];
    var idxKec = 0;
    var btnKec = E("button", "tbl-kecepatan", "1x");
    btnKec.type = "button";
    btnKec.title = "Atur kecepatan putar (bagus untuk latihan menyimak)";

    // 5. Volume
    var wadahVol = E("div", "wadah-volume");
    var btnVol = E("button", "tbl-volume");
    btnVol.type = "button";
    btnVol.title = "Bisukan / Bunyikan";
    btnVol.innerHTML = '<svg class="ikon-vol" viewBox="0 0 24 24"><path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02z" fill="currentColor"/></svg>';
    var sliderVol = document.createElement("input");
    sliderVol.type = "range";
    sliderVol.className = "slider-volume";
    sliderVol.min = "0"; sliderVol.max = "1"; sliderVol.step = "0.05"; sliderVol.value = "1";
    wadahVol.appendChild(btnVol);
    wadahVol.appendChild(sliderVol);

    baris.appendChild(btnPlay);
    baris.appendChild(btnMundur);
    baris.appendChild(btnMaju);
    baris.appendChild(linimasa);
    baris.appendChild(btnKec);
    baris.appendChild(wadahVol);
    bungkus.appendChild(baris);

    // 6. Animasi Gelombang Suara
    var gelombang = E("div", "efek-gelombang");
    for (var g = 0; g < 8; g++) gelombang.appendChild(document.createElement("span"));
    bungkus.appendChild(gelombang);

    function formatWaktu(dtk) {
      if (isNaN(dtk) || dtk < 0) return "00:00";
      var m = Math.floor(dtk / 60);
      var s = Math.floor(dtk % 60);
      return (m < 10 ? "0" + m : m) + ":" + (s < 10 ? "0" + s : s);
    }

    btnPlay.addEventListener("click", function () {
      if (audio.paused) {
        document.querySelectorAll("audio").forEach(function (a) {
          if (a !== audio) try { a.pause(); } catch (e) { }
        });
        audio.play().catch(function () { });
      } else {
        audio.pause();
      }
    });

    audio.addEventListener("play", function () { bungkus.classList.add("memutar"); });
    audio.addEventListener("pause", function () { bungkus.classList.remove("memutar"); });
    audio.addEventListener("ended", function () {
      bungkus.classList.remove("memutar");
      relIsi.style.width = "0%";
      teksKini.textContent = "00:00";
    });

    audio.addEventListener("timeupdate", function () {
      if (!audio.duration) return;
      var persen = (audio.currentTime / audio.duration) * 100;
      relIsi.style.width = persen + "%";
      teksKini.textContent = formatWaktu(audio.currentTime);
    });

    audio.addEventListener("loadedmetadata", function () {
      teksTotal.textContent = formatWaktu(audio.duration);
    });

    function lompatWaktu(ev) {
      var rect = rel.getBoundingClientRect();
      var x = Math.max(0, Math.min(ev.clientX - rect.left, rect.width));
      var targetPersen = x / rect.width;
      if (audio.duration) {
        audio.currentTime = targetPersen * audio.duration;
      }
    }
    rel.addEventListener("click", lompatWaktu);

    btnMundur.addEventListener("click", function () {
      audio.currentTime = Math.max(0, audio.currentTime - 5);
    });
    btnMaju.addEventListener("click", function () {
      if (audio.duration) audio.currentTime = Math.min(audio.duration, audio.currentTime + 5);
    });

    btnKec.addEventListener("click", function () {
      idxKec = (idxKec + 1) % daftarKec.length;
      var kec = daftarKec[idxKec];
      audio.playbackRate = kec;
      btnKec.textContent = kec + "x";
    });

    sliderVol.addEventListener("input", function () {
      audio.volume = parseFloat(sliderVol.value);
      audio.muted = (audio.volume === 0);
    });
    btnVol.addEventListener("click", function () {
      audio.muted = !audio.muted;
      sliderVol.value = audio.muted ? 0 : audio.volume;
    });

    wadahPemutar.appendChild(bungkus);

    return {
      audio: audio,
      bungkus: bungkus,
      setSumber: function (url, fallbackEmbedUrl) {
        audio.src = url;
        audio.load();
        if (fallbackEmbedUrl) {
          audio.onerror = function () {
            // Jika direct stream dibatasi, beralih ke preview iframe
            bungkus.style.display = "none";
            var ifrFallback = wadahPemutar.querySelector("iframe.media-embed");
            if (!ifrFallback) {
              ifrFallback = document.createElement("iframe");
              ifrFallback.className = "audio-embed media-embed";
              ifrFallback.setAttribute("allowfullscreen", "");
              ifrFallback.setAttribute("allow", "autoplay");
              wadahPemutar.appendChild(ifrFallback);
            }
            ifrFallback.src = fallbackEmbedUrl;
            ifrFallback.style.display = "block";
          };
        }
      }
    };
  }

  /* ---------- kotak media ---------- */
  function buatMedia(b, hal) {
    var jenisVideo = (b.j === "video");
    var kotak = E("div", "media");
    var alamat = (MEDIA_KUSTOM && MEDIA_KUSTOM[b.kode]) || MEDIA[b.kode] || ("media/" + b.kode + (jenisVideo ? ".mp4" : ".mp3"));
    kotak.innerHTML =
      '<div class="kop"><span class="kode">' + (jenisVideo ? '<svg class="media-ikon-tipe" viewBox="0 0 24 24" width="13" height="13" fill="currentColor"><path d="M17 10.5V7c0-.55-.45-1-1-1H4c-.55 0-1 .45-1 1v10c0 .55.45 1 1 1h12c.55 0 1-.45 1-1v-3.5l4 4v-11l-4 4z"/></svg> VIDEO' : '<svg class="media-ikon-tipe" viewBox="0 0 24 24" width="13" height="13" fill="currentColor"><path d="M12 3v10.55c-.59-.34-1.27-.55-2-.55-2.21 0-4 1.79-4 4s1.79 4 4 4 4-1.79 4-4V7h4V3h-6z"/></svg> AUDIO') + " · " + b.kode.toUpperCase() +
      '</span>' + (b.durasi ? '<span class="durasi">⏱ ' + b.durasi + '</span>' : '') + '</div>' +
      "<h4>" + b.judul + "</h4>" +
      (b.ket ? '<p class="media-petunjuk">' + b.ket + "</p>" : "");

    var wadahPemutar = E("div", "wadah-pemutar");
    var pemutarVideo = null;
    var pemutarAudioKustom = null;

    if (jenisVideo) {
      pemutarVideo = document.createElement("video");
      pemutarVideo.controls = true;
      pemutarVideo.preload = "none";
      pemutarVideo.setAttribute("playsinline", "");
      wadahPemutar.appendChild(pemutarVideo);
    } else {
      pemutarAudioKustom = bangunPemutarAudioKustom(wadahPemutar);
    }
    kotak.appendChild(wadahPemutar);

    var kaki = E("div", "kaki");
    var nama = E("span", "badge-status");

    function pasangSumberMedia(url) {
      var embed = periksaVideoEmbed(url);

      if (jenisVideo) {
        /* PENGELOLAAN VIDEO */
        if (embed) {
          if (pemutarVideo) {
            pemutarVideo.style.display = "none";
            pemutarVideo.removeAttribute("src");
            try { pemutarVideo.pause(); } catch (e) { }
          }
          var ifrV = wadahPemutar.querySelector("iframe.video-embed");
          if (!ifrV) {
            ifrV = document.createElement("iframe");
            ifrV.className = "video-embed media-embed";
            ifrV.setAttribute("allowfullscreen", "");
            ifrV.setAttribute("allow", "accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share");
            wadahPemutar.appendChild(ifrV);
          }
          ifrV.src = embed.src;
          ifrV.style.display = "block";
          nama.innerHTML = '<span class="titik"></span> ' + (embed.tipe === "youtube" ? "YouTube" : "Google Drive");
        } else {
          var ifrSisaV = wadahPemutar.querySelector("iframe.video-embed");
          if (ifrSisaV) { ifrSisaV.src = ""; ifrSisaV.style.display = "none"; }
          if (pemutarVideo) {
            pemutarVideo.style.display = "block";
            pemutarVideo.src = url;
            pemutarVideo.load();
          }
          nama.innerHTML = (MEDIA_KUSTOM && MEDIA_KUSTOM[b.kode]) ?
            '<span class="titik"></span> Video Kustom' :
            '<span class="titik" style="background:#d9a441;box-shadow:0 0 6px #d9a441"></span> Video Bawaan';
        }
      } else {
        /* PENGELOLAAN AUDIO (PEMUTAR MEWAH EMAS) */
        var ifrAudio = wadahPemutar.querySelector("iframe.media-embed");
        if (ifrAudio) { ifrAudio.src = ""; ifrAudio.style.display = "none"; }

        if (embed && embed.tipe === "youtube") {
          // YouTube Audio: tampilkan iframe player
          if (pemutarAudioKustom) pemutarAudioKustom.bungkus.style.display = "none";
          var ifrYt = wadahPemutar.querySelector("iframe.media-embed");
          if (!ifrYt) {
            ifrYt = document.createElement("iframe");
            ifrYt.className = "video-embed media-embed";
            ifrYt.setAttribute("allowfullscreen", "");
            ifrYt.setAttribute("allow", "accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share");
            wadahPemutar.appendChild(ifrYt);
          }
          ifrYt.src = embed.src;
          ifrYt.style.display = "block";
          nama.innerHTML = '<span class="titik"></span> YouTube';

        } else if (embed && embed.tipe === "drive") {
          // Google Drive Audio: Putar langsung di Pemutar Kustom Mewah via stream resmi
          if (pemutarAudioKustom) {
            pemutarAudioKustom.bungkus.style.display = "block";
            var streamUrl = "https://drive.usercontent.google.com/download?id=" + embed.id + "&export=download";
            pemutarAudioKustom.setSumber(streamUrl, embed.src);
          }
          nama.innerHTML = '<span class="titik"></span> Google Drive';

        } else {
          // Berkas audio langsung (MP3 daring atau berkas bawaan)
          if (pemutarAudioKustom) {
            pemutarAudioKustom.bungkus.style.display = "block";
            pemutarAudioKustom.setSumber(url);
          }
          nama.innerHTML = (MEDIA_KUSTOM && MEDIA_KUSTOM[b.kode]) ?
            '<span class="titik"></span> Audio Kustom' :
            '<span class="titik" style="background:#d9a441;box-shadow:0 0 6px #d9a441"></span> Berkas Bawaan';
        }
      }

      if (btnReset) {
        btnReset.style.display = (MEDIA_KUSTOM && MEDIA_KUSTOM[b.kode]) ? "inline-flex" : "none";
      }
    }

    var btnLink = null;
    var btnReset = null;

    if (ADMIN) {
      var grupAdmin = E("div", "grup-tombol-admin");

      btnLink = E("button", "tbl-admin-link", jenisVideo ? "🔗 Ganti Video (Drive / YouTube)" : "🔗 Ganti Audio (Drive / YouTube)");
      btnLink.type = "button";
      btnLink.title = "Atur tautan Google Drive atau YouTube";
      btnLink.addEventListener("click", function () {
        var skrg = MEDIA_KUSTOM[b.kode] || alamat;
        var pesan = "ATUR TAUTAN " + (jenisVideo ? "VIDEO" : "AUDIO") + " (" + b.kode.toUpperCase() + "):\n\n" +
          "• Tautan YouTube (contoh: https://www.youtube.com/watch?v=... atau https://youtu.be/...)\n" +
          "• Tautan Google Drive (contoh: https://drive.google.com/file/d/.../view)\n" +
          "• Atau tautan berkas daring langsung (.mp3 / .mp4)\n\n" +
          "Catatan: Disimpan secara online ke basis data Supabase (bebas kuota localStorage).\n\n" +
          "Tautan saat ini: " + skrg;
        var masukkan = window.prompt(pesan, (MEDIA_KUSTOM[b.kode] || ""));
        if (masukkan === null) return;
        var teks = masukkan.trim();
        if (teks) {
          MEDIA_KUSTOM[b.kode] = teks;
          pasangSumberMedia(teks);
          simpanMediaKustom(function (ok, err) {
            if (ok) {
              window.alert((jenisVideo ? "Tautan video" : "Tautan audio") + " berhasil disimpan ke Supabase!");
            } else {
              window.alert("Gagal menyimpan ke Supabase: " + (err || "error"));
            }
          });
        }
      });

      btnReset = E("button", "tbl-admin-reset", "↺ Bawaan");
      btnReset.type = "button";
      btnReset.title = "Hapus media kustom dan kembali ke berkas awal";
      btnReset.style.display = (MEDIA_KUSTOM && MEDIA_KUSTOM[b.kode]) ? "inline-flex" : "none";
      btnReset.addEventListener("click", function () {
        if (window.confirm("Hapus media kustom dan kembalikan ke berkas bawaan?")) {
          delete MEDIA_KUSTOM[b.kode];
          var asal = MEDIA[b.kode] || ("media/" + b.kode + (jenisVideo ? ".mp4" : ".mp3"));
          pasangSumberMedia(asal);
          simpanMediaKustom(function () {
            window.alert("Media dikembalikan ke berkas bawaan modul.");
          });
        }
      });

      grupAdmin.appendChild(btnLink);
      grupAdmin.appendChild(btnReset);
      kaki.appendChild(grupAdmin);
    }

    kaki.appendChild(nama);
    kotak.appendChild(kaki);

    /* Pasang sumber awal dan daftarkan pembaruan otomatis saat data Supabase tiba */
    pasangSumberMedia(alamat);
    daftarkanPemasangMedia(b.kode, function (urlBaru) {
      pasangSumberMedia(urlBaru);
    });

    kotak.appendChild(E("div", "cetak-saja",
      (jenisVideo ? "VIDEO" : "AUDIO") + " — " + alamat + (b.durasi ? " (" + b.durasi + ")" : "") + ". Putar dari perangkat pengajar."));
    return kotak;
  }





  /* ---------- latihan: pilihan ganda ---------- */
  function buatPantau() {
    var bungkus = E("div");

    /* ---------- keadaan sambungan ---------- */
    var papan = E("div", "borang");
    papan.appendChild(E("h4", null, "Keadaan basis data"));
    var kabar = E("p", "arahan", "Memeriksa sambungan\u2026");
    papan.appendChild(kabar);
    var tautan = E("p", "arahan",
      'Berkas basis data: <a href="https://docs.google.com/spreadsheets/d/' + ID_BASISDATA +
      '/edit" target="_blank" rel="noopener">buka MYBIPA_DATABASE di Google Spreadsheet</a>.');
    papan.appendChild(tautan);

    var angka = E("div", "pantau-angka");
    papan.appendChild(angka);

    var tuas = E("div", "tuas-borang");
    var tbSegar = document.createElement("button"); tbSegar.type = "button"; tbSegar.textContent = "Muat ulang";
    var tbKirim = document.createElement("button"); tbKirim.type = "button"; tbKirim.className = "hening";
    tbKirim.textContent = "Kirim ulang semua data ke basis data";
    var tbCsv = document.createElement("button"); tbCsv.type = "button"; tbCsv.className = "hening";
    tbCsv.textContent = "Unduh seluruh data (.csv)";
    var tbLog = document.createElement("button"); tbLog.type = "button"; tbLog.className = "hening";
    tbLog.textContent = "Unduh riwayat kegiatan (.csv)";
    var tbUji = document.createElement("button"); tbUji.type = "button"; tbUji.className = "hening";
    tbUji.textContent = "Kirim satu data uji";
    tuas.appendChild(tbSegar); tuas.appendChild(tbUji); tuas.appendChild(tbKirim);
    tuas.appendChild(tbCsv); tuas.appendChild(tbLog);
    papan.appendChild(tuas);
    var pesanKirim = E("p", "pesan-borang", "");
    papan.appendChild(pesanKirim);
    bungkus.appendChild(papan);

    /* ---------- daftar akun ---------- */
    var judulAkun = E("h4", "pantau-judul", "Seluruh akun terdaftar");
    bungkus.appendChild(judulAkun);
    var daftar = E("div", "pantau-daftar");
    bungkus.appendChild(daftar);

    /* ---------- riwayat kegiatan ---------- */
    bungkus.appendChild(E("h4", "pantau-judul", "Riwayat kegiatan pada perangkat ini"));
    var riwayat = E("div", "pantau-riwayat");
    bungkus.appendChild(riwayat);

    function semuaAkun() {
      var akun = bacaGudang(KUNCI_AKUN, {});
      var rekap = bacaGudang(KUNCI_REKAP, {});
      return Object.keys(akun).map(function (k) {
        var a = akun[k], r = rekap[k] || {};
        return {
          nama: a.nama, surel: a.surel, wa: a.wa || "", instansi: a.instansi || "",
          dosen: a.dosen || "", peran: a.peran || "pemelajar", dibuat: a.dibuat || "",
          unit: r.unit || [], tuntas: r.tuntas || 0, rata: r.rata || 0,
          lengkap: !!r.lengkap, diperbarui: r.diperbarui || ""
        };
      }).sort(function (x, y) {
        var urut = { admin: 0, pengajar: 1, pemelajar: 2 };
        if (urut[x.peran] !== urut[y.peran]) return urut[x.peran] - urut[y.peran];
        return x.nama.localeCompare(y.nama);
      });
    }

    function tanggalPendek(t) {
      if (!t) return "\u2013";
      var d = new Date(t);
      if (isNaN(d.getTime())) return "\u2013";
      return d.toLocaleString("id-ID", {
        day: "2-digit", month: "short", year: "numeric",
        hour: "2-digit", minute: "2-digit"
      });
    }

    function gambar() {
      var isi = semuaAkun();
      var jumlah = { pemelajar: 0, pengajar: 0, admin: 0, tuntas: 0, nilai: 0, berpenilaian: 0 };
      isi.forEach(function (x) {
        jumlah[x.peran] = (jumlah[x.peran] || 0) + 1;
        if (x.lengkap) jumlah.tuntas++;
        if (x.tuntas > 0) { jumlah.nilai += x.rata; jumlah.berpenilaian++; }
      });
      angka.innerHTML =
        '<div class="pa"><b>' + (jumlah.pemelajar || 0) + "</b><span>pemelajar</span></div>" +
        '<div class="pa"><b>' + (jumlah.pengajar || 0) + "</b><span>pengajar</span></div>" +
        '<div class="pa"><b>' + (jumlah.admin || 0) + "</b><span>admin</span></div>" +
        '<div class="pa"><b>' + jumlah.tuntas + "</b><span>tuntas 11 unit</span></div>" +
        '<div class="pa"><b>' + (jumlah.berpenilaian ? Math.round(jumlah.nilai / jumlah.berpenilaian) : "\u2013") +
        "</b><span>rata-rata nilai</span></div>";

      if (!isi.length) {
        daftar.innerHTML = '<p class="kelas-kosong">Belum ada akun pada perangkat ini.</p>';
      } else {
        daftar.innerHTML = isi.map(function (x) {
          var kotakUnit = "";
          for (var i = 0; i < 11; i++) {
            var v = x.unit[i];
            var ada = v !== null && v !== undefined && v !== "";
            kotakUnit += '<span class="ku' + (ada ? " isi" : "") + '">' + (ada ? v : "\u2013") + "</span>";
          }
          return '<div class="kelas-kartu">' +
            '<div class="kk-kop"><b>' + x.nama + "</b>" +
            '<span class="peran-cap ' + x.peran + '">' + x.peran + "</span>" +
            (x.peran === "pemelajar"
              ? '<span class="kk-cap' + (x.lengkap ? " tuntas" : "") + '">' +
              (x.lengkap ? "Tuntas \u00b7 " + x.rata + " \u00b7 " + predikatNilai(x.rata)
                : x.tuntas + " dari 11 unit") + "</span>"
              : "") + "</div>" +
            '<div class="kk-data">' + (x.instansi || "\u2013") + " \u00b7 " + (x.surel || "\u2013") +
            (x.wa && x.wa !== "-" ? " \u00b7 " + x.wa : "") + "</div>" +
            (x.dosen ? '<div class="kk-data">Pengajar: ' + x.dosen + "</div>" : "") +
            '<div class="kk-data">Terdaftar ' + tanggalPendek(x.dibuat) +
            (x.diperbarui ? " \u00b7 terakhir aktif " + tanggalPendek(x.diperbarui) : "") + "</div>" +
            (x.peran === "pemelajar" ? '<div class="kk-unit">' + kotakUnit + "</div>" : "") +
            "</div>";
        }).join("");
      }

      var log = bacaGudang(KUNCI_LOG, []).slice().reverse();
      riwayat.innerHTML = log.length
        ? log.slice(0, 60).map(function (x) {
          return '<div class="pr"><span class="pr-waktu">' + tanggalPendek(x.waktu) + "</span>" +
            '<span class="pr-nama">' + (x.nama || "\u2013") + "</span>" +
            '<span class="pr-jenis">' + x.jenis + (x.ket ? " \u00b7 " + x.ket : "") + "</span></div>";
        }).join("")
        : '<p class="kelas-kosong">Belum ada kegiatan tercatat pada perangkat ini.</p>';
    }

    function periksaSambungan() {
      kabar.textContent = "Memeriksa sambungan\u2026";
      ujiSambunganBasisData(function (h) {
        var warna = {
          penuh: "#2F6B48", sebagian: "#B8862B", galat: "#9B3B23",
          putus: "#9B3B23", kosong: "#9B3B23"
        }[h.keadaan] || "#5A4A40";
        var judul = {
          penuh: "Tersambung penuh.", sebagian: "Pengiriman berjalan.",
          galat: "Ada galat pada skrip.", putus: "Belum dapat dihubungi.",
          kosong: "Alamat belum diisi."
        }[h.keadaan];
        kabar.style.color = warna;
        kabar.innerHTML = "<b>" + judul + "</b> " + h.pesanPendek;
      });
    }

    tbSegar.addEventListener("click", function () { gambar(); periksaSambungan(); });

    tbUji.addEventListener("click", function () {
      if (!URL_SINKRON) { pesanKirim.textContent = "Alamat penghubung basis data belum diisi."; return; }
      kirimSinkron({
        aksi: "simpan", catatan: "data uji dari panel admin", peran: "pemelajar", tingkat: TINGKAT_MODUL,
        nama: "Data Uji " + new Date().toLocaleTimeString("id-ID"),
        surel: "uji" + Date.now() + "@mybipa.test", wa: "0800", instansi: "Uji Coba", dosen: "",
        unit: [85, 80, null, null, null, null, null, null, null, null, null],
        tuntas: 2, rata: 83, lengkap: false, penuh: {}
      });
      pesanKirim.style.color = "#5A4A40";
      pesanKirim.textContent = "Data uji dikirim. Buka lembar Pemelajar dan Aktivitas pada spreadsheet " +
        "sekitar lima detik lagi. Bila barisnya bertambah, pencatatan sudah berjalan. Hapus baris uji setelah diperiksa.";
    });

    tbKirim.addEventListener("click", function () {
      if (!URL_SINKRON) { pesanKirim.textContent = "Alamat penghubung basis data belum diisi."; return; }
      var isi = semuaAkun();
      pesanKirim.style.color = "#5A4A40";
      pesanKirim.textContent = "Mengirim " + isi.length + " data\u2026";
      var ke = 0;
      function kirimSatu() {
        if (ke >= isi.length) {
          pesanKirim.style.color = "#2F6B48";
          pesanKirim.textContent = "Selesai. " + isi.length +
            " data dikirim ke basis data. Periksa lembar Pemelajar, Pengajar, dan Aktivitas.";
          return;
        }
        var x = isi[ke++];
        kirimSinkron({
          aksi: "simpan", catatan: "kirim ulang oleh admin", peran: x.peran, tingkat: TINGKAT_MODUL,
          nama: x.nama, surel: x.surel, wa: x.wa, instansi: x.instansi, dosen: x.dosen,
          unit: x.unit, tuntas: x.tuntas, rata: x.rata, lengkap: x.lengkap, penuh: {}
        });
        setTimeout(kirimSatu, 900);
      }
      kirimSatu();
    });

    function unduhCsv(namaBerkas, baris) {
      var csv = baris.map(function (r) {
        return r.map(function (sel) { return '"' + String(sel).replace(/"/g, '""') + '"'; }).join(",");
      }).join("\n");
      var berkas = new Blob(["\ufeff" + csv], { type: "text/csv;charset=utf-8" });
      var a = document.createElement("a");
      a.href = URL.createObjectURL(berkas);
      a.download = namaBerkas;
      a.click();
      setTimeout(function () { URL.revokeObjectURL(a.href); }, 4000);
    }

    tbCsv.addEventListener("click", function () {
      var baris = [["Nama", "Peran", "Surel", "WhatsApp", "Instansi", "Pengajar",
        "U1", "U2", "U3", "U4", "U5", "U6", "U7", "U8", "U9", "U10", "U11",
        "Unit tuntas", "Nilai akhir", "Predikat", "Terdaftar", "Terakhir aktif"]];
      semuaAkun().forEach(function (x) {
        var r = [x.nama, x.peran, x.surel, x.wa, x.instansi, x.dosen];
        for (var i = 0; i < 11; i++) {
          var v = x.unit[i];
          r.push(v === null || v === undefined ? "" : v);
        }
        r.push(x.tuntas, x.rata, x.lengkap ? predikatNilai(x.rata) : "belum tuntas",
          x.dibuat, x.diperbarui);
        baris.push(r);
      });
      unduhCsv("data-pengguna-mybipa-a2.csv", baris);
    });

    tbLog.addEventListener("click", function () {
      var baris = [["Waktu", "Nama", "Surel", "Peran", "Kegiatan", "Keterangan"]];
      bacaGudang(KUNCI_LOG, []).forEach(function (x) {
        baris.push([x.waktu, x.nama, x.surel, x.peran, x.jenis, x.ket]);
      });
      unduhCsv("riwayat-kegiatan-mybipa-a2.csv", baris);
    });

    setTimeout(function () { gambar(); periksaSambungan(); }, 0);
    return bungkus;
  }

  function buatKelas() {
    var bungkus = E("div");
    var alat = E("div", "borang");
    alat.appendChild(E("h4", null, ADMIN ? "Seluruh pemelajar terdaftar" : "Pemelajar bimbingan Anda"));
    alat.appendChild(E("p", "arahan", ADMIN
      ? "Sebagai admin, Anda melihat seluruh akun pada perangkat ini beserta data dari spreadsheet apabila penyelarasan sudah dipasang."
      : "Daftar berikut memuat pemelajar yang menuliskan nama Anda pada kolom pengajar saat mendaftar."));
    var cari = document.createElement("input");
    cari.type = "search"; cari.placeholder = "Cari nama atau instansi\u2026";
    cari.className = "cari-kelas";
    alat.appendChild(cari);
    var tuas = E("div", "tuas-borang");
    var tbSegar = document.createElement("button");
    tbSegar.type = "button"; tbSegar.textContent = "Muat ulang data";
    var tbUnduh = document.createElement("button");
    tbUnduh.type = "button"; tbUnduh.className = "hening"; tbUnduh.textContent = "Unduh rekap kelas (.csv)";
    tuas.appendChild(tbSegar); tuas.appendChild(tbUnduh);
    alat.appendChild(tuas);
    var kabar = E("p", "pesan-borang", "");
    alat.appendChild(kabar);
    bungkus.appendChild(alat);

    var daftar = E("div", "kelas-daftar");
    bungkus.appendChild(daftar);

    function kumpulkan() {
      var semua = bacaGudang(KUNCI_REKAP, {});
      var akun = bacaGudang(KUNCI_AKUN, {});
      var hasil = [];
      Object.keys(akun).forEach(function (k) {
        var a = akun[k];
        if (a.peran === "admin" || a.peran === "pengajar") return;
        if (!ADMIN) {
          var milik = String(a.dosen || "").toLowerCase().replace(/\s+/g, " ").trim();
          var saya = String(AKUN ? AKUN.nama : "").toLowerCase().replace(/\s+/g, " ").trim();
          if (!milik || milik.indexOf(saya) < 0) return;
        }
        var r = semua[k] || {};
        hasil.push({
          nama: a.nama, surel: a.surel, wa: a.wa, instansi: a.instansi, dosen: a.dosen || "",
          unit: r.unit || [], tuntas: r.tuntas || 0, rata: r.rata || 0,
          lengkap: !!r.lengkap, diperbarui: r.diperbarui || ""
        });
      });
      hasil.sort(function (a, b) { return a.nama.localeCompare(b.nama); });
      return hasil;
    }

    var ISI = [];
    function gambar() {
      var kata = cari.value.toLowerCase().trim();
      var tampil = ISI.filter(function (x) {
        if (!kata) return true;
        return (x.nama + " " + x.instansi).toLowerCase().indexOf(kata) >= 0;
      });
      if (!tampil.length) {
        daftar.innerHTML = '<p class="kelas-kosong">Belum ada pemelajar yang tercatat' +
          (ADMIN ? " pada perangkat ini." : " dengan nama Anda sebagai pengajar.") + "</p>";
        return;
      }
      var potong = tampil.map(function (x) {
        var kotakUnit = "";
        for (var i = 0; i < 11; i++) {
          var nilai = x.unit[i];
          var ada = nilai !== null && nilai !== undefined && nilai !== "";
          kotakUnit += '<span class="ku' + (ada ? " isi" : "") + '" title="Unit ' + (i + 1) + '">' +
            (ada ? nilai : "\u2013") + "</span>";
        }
        return '<div class="kelas-kartu">' +
          '<div class="kk-kop"><b>' + x.nama + "</b>" +
          '<span class="kk-cap' + (x.lengkap ? " tuntas" : "") + '">' +
          (x.lengkap ? "Tuntas \u00b7 " + x.rata + " \u00b7 " + predikatNilai(x.rata)
            : x.tuntas + " dari 11 unit") + "</span></div>" +
          '<div class="kk-data">' + x.instansi + " \u00b7 " + x.surel +
          (x.wa ? " \u00b7 " + x.wa : "") + "</div>" +
          (x.dosen ? '<div class="kk-data">Pengajar: ' + x.dosen + "</div>" : "") +
          '<div class="kk-unit">' + kotakUnit + "</div>" +
          "</div>";
      });
      daftar.innerHTML = potong.join("");
    }

    function muat() {
      ISI = kumpulkan();
      gambar();
      kabar.textContent = "";
      if (URL_SINKRON && AKUN) {
        kabar.style.color = "#5A4A40";
        kabar.textContent = "Mengambil data dari spreadsheet\u2026";
        bacaBasisData({ aksi: "kelas", dosen: (ADMIN ? "*" : AKUN.nama), surel: AKUN.surel, tingkat: TINGKAT_MODUL }, function (j) {
          if (j && j.ok && j.data && j.data.length) {
            var kenal = {};
            ISI.forEach(function (x) { kenal[x.surel] = x; });
            j.data.forEach(function (x) {
              if (kenal[x.surel]) return;
              ISI.push({
                nama: x.nama, surel: x.surel, wa: x.wa, instansi: x.instansi, dosen: x.dosen || "",
                unit: x.unit || [], tuntas: x.tuntas || 0, rata: x.rata || 0,
                lengkap: (x.tuntas || 0) >= 11, diperbarui: ""
              });
            });
            ISI.sort(function (a, b) { return a.nama.localeCompare(b.nama); });
            gambar();
            kabar.textContent = "Data spreadsheet ikut ditampilkan.";
          } else if (j) {
            kabar.textContent = "Spreadsheet belum memuat data untuk kelas ini.";
          } else {
            kabar.style.color = "#9B3B23";
            kabar.textContent = "Data spreadsheet belum dapat diambil. Daftar di bawah berasal dari perangkat ini.";
          }
        });
      } else if (!URL_SINKRON) {
        kabar.textContent = "Penyelarasan spreadsheet belum dipasang, sehingga daftar ini hanya memuat akun pada perangkat ini.";
      }
    }

    cari.addEventListener("input", gambar);
    tbSegar.addEventListener("click", muat);
    tbUnduh.addEventListener("click", function () {
      var baris = [["Nama", "Surel", "WhatsApp", "Instansi", "Pengajar", "Unit tuntas", "Nilai akhir", "Predikat"]];
      ISI.forEach(function (x) {
        baris.push([x.nama, x.surel, x.wa, x.instansi, x.dosen, x.tuntas, x.rata,
        x.lengkap ? predikatNilai(x.rata) : "belum tuntas"]);
      });
      var csv = baris.map(function (r) {
        return r.map(function (sel) { return '"' + String(sel).replace(/"/g, '""') + '"'; }).join(",");
      }).join("\n");
      var berkas = new Blob(["\ufeff" + csv], { type: "text/csv;charset=utf-8" });
      var a = document.createElement("a");
      a.href = URL.createObjectURL(berkas);
      a.download = "rekap-kelas-mybipa-a2.csv";
      a.click();
    });

    setTimeout(muat, 0);
    return bungkus;
  }

  function buatSertifikat() {
    var bungkus = E("div");

    /* ---------- rekap kemajuan ---------- */
    var papan = E("div", "borang");
    papan.appendChild(E("h4", null, "Kemajuan dan nilai Anda"));
    var daftarUnit = E("div", "rekap-unit");
    papan.appendChild(daftarUnit);
    var ringkas = E("div", "papan-nilai");
    var angkaAkhir = E("b", null, "\u2013");
    var capAkhir = E("span", "cap tunggu", "Belum lengkap");
    var ketAkhir = E("span", "ket", "");
    ringkas.appendChild(E("span", "ket", "Nilai akhir:"));
    ringkas.appendChild(angkaAkhir); ringkas.appendChild(capAkhir); ringkas.appendChild(ketAkhir);
    papan.appendChild(ringkas);
    var pesan = E("p", "pesan-borang", "");
    papan.appendChild(pesan);

    /* ---------- kolom yang hanya boleh diubah admin ---------- */
    var borangAdmin = E("div", "borang");
    if (PENGELOLA) {
      borangAdmin.appendChild(E("h4", null, "Pengaturan penerbitan (pengelola)"));
      borangAdmin.appendChild(E("p", "arahan",
        "Kolom berikut hanya tampil bagi admin. Pemelajar melihat sertifikat yang sudah terisi sendiri."));
      var b1 = E("div", "baris-isian");
      function isian(induk, kunci, judul, tipe) {
        var k = E("div", "isian");
        var lb = document.createElement("label");
        lb.setAttribute("for", "srt-" + kunci); lb.textContent = judul;
        var inp = document.createElement("input");
        inp.type = tipe; inp.id = "srt-" + kunci; inp.dataset.kunci = kunci;
        inp.value = DATA_SRT[kunci] || "";
        k.appendChild(lb); k.appendChild(inp); induk.appendChild(k);
        return inp;
      }
      isian(b1, "pengajar", "Nama pengajar penanggung jawab", "text");
      isian(b1, "jabatan", "Jabatan pengajar", "text");
      isian(b1, "penandatangan", "Pejabat penanda tangan kedua", "text");
      isian(b1, "jabatan2", "Jabatan penanda tangan kedua", "text");
      isian(b1, "penyelenggara", "Penyelenggara kegiatan", "text");
      isian(b1, "tanggal", "Tanggal uji kompetensi", "date");
      borangAdmin.appendChild(b1);
      borangAdmin.addEventListener("input", function (ev) {
        var inp = ev.target;
        if (!inp || !inp.dataset || !inp.dataset.kunci) return;
        DATA_SRT[inp.dataset.kunci] = inp.value;
        simpanSertifikat(); segarkanSertifikat();
      });
    }

    var tuas = E("div", "tuas-borang");
    var tbCetak = document.createElement("button"); tbCetak.type = "button"; tbCetak.textContent = "Cetak sertifikat";
    tuas.appendChild(tbCetak);
    papan.appendChild(tuas);

    bungkus.appendChild(papan);
    if (PENGELOLA) bungkus.appendChild(borangAdmin);

    var panggungSrt = E("div", "srt-panggung");
    var lembar = E("div", "srt");
    lembar.id = "lembar-sertifikat";
    lembar.innerHTML = RANGKA_SERTIFIKAT;
    panggungSrt.appendChild(lembar);
    var kunciSrt = E("div", "srt-kunci");
    kunciSrt.innerHTML = '<span class="gembok">\uD83D\uDD12</span>' +
      "<b>Sertifikat belum terbuka</b>" +
      "<span>Selesaikan seluruh sebelas unit terlebih dahulu. Lembar sertifikat akan muncul sendiri di sini.</span>";
    bungkus.appendChild(kunciSrt);
    bungkus.appendChild(panggungSrt);

    function amb(k) { return lembar.querySelector("[data-s='" + k + "']"); }
    var BULAN = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus",
      "September", "Oktober", "November", "Desember"];
    function tanggalPanjang(t) {
      if (!t) return new Date().getDate() + " " + BULAN[new Date().getMonth()] + " " + new Date().getFullYear();
      var bg = String(t).split("-");
      if (bg.length !== 3) return t;
      return parseInt(bg[2], 10) + " " + (BULAN[parseInt(bg[1], 10) - 1] || "") + " " + bg[0];
    }

    segarkanSertifikat = function () {
      var r = rekapSemuaUnit();
      var nama = AKUN ? AKUN.nama : "";
      var instansi = AKUN ? AKUN.instansi : "";

      /* daftar nilai per unit: baris dibuat sekali, isinya diperbarui saja
         agar kolom nilai admin tidak kehilangan fokus saat diketik */
      if (!daftarUnit.children.length) {
        var potong = [];
        r.daftar.forEach(function (d) {
          potong.push('<div class="ru" data-unit="' + d.no + '">' +
            '<span class="ru-no">U' + d.no + '</span>' +
            '<span class="ru-judul">' + d.judul + '</span>' +
            '<span class="ru-nilai">\u2013</span>' +
            (PENGELOLA ? '<input class="ru-timpa" type="number" min="0" max="100" data-unit="' + d.no +
              '" value="' + (NILAI_TIMPA[d.no] !== undefined ? NILAI_TIMPA[d.no] : "") +
              '" placeholder="ubah" title="Ubah nilai unit ini">' : "") +
            '</div>');
        });
        daftarUnit.innerHTML = potong.join("");
      }
      r.daftar.forEach(function (d) {
        var baris = daftarUnit.querySelector('.ru[data-unit="' + d.no + '"]');
        if (!baris) return;
        var siap = d.hasil.tuntas || d.hasil.timpa;
        baris.classList.toggle("siap", siap);
        baris.querySelector(".ru-nilai").textContent = siap ? d.hasil.nilai : "\u2013";
      });

      angkaAkhir.textContent = r.tuntas ? r.rata : "\u2013";
      capAkhir.textContent = r.lengkap ? predikatNilai(r.rata) : "Belum lengkap";
      capAkhir.className = "cap" + (r.lengkap ? (r.rata < 60 ? " kurang" : "") : " tunggu");
      ketAkhir.textContent = r.tuntas + " dari " + r.total + " unit tuntas";

      var layak = r.lengkap && r.rata >= 60 && nama;
      if (!AKUN) pesan.textContent = "Masuk ke akun Anda lebih dahulu agar sertifikat dapat diterbitkan.";
      else if (!r.lengkap) pesan.textContent = "Masih ada " + (r.total - r.tuntas) +
        " unit yang belum tuntas. Sertifikat terbuka setelah seluruh unit selesai.";
      else if (r.rata < 60) pesan.textContent = "Nilai akhir " + r.rata +
        " belum mencapai 60, sehingga sertifikat belum dapat diterbitkan.";
      else pesan.textContent = "";
      tbCetak.disabled = !layak;
      kunciSrt.style.display = layak ? "none" : "";
      panggungSrt.style.display = layak ? "" : "none";
      if (!layak) return;

      amb("nomor").textContent = DATA_SRT.nomor || "";
      amb("nama").textContent = nama;
      amb("level").textContent = "Dasar (A2)";
      amb("nilai").textContent = r.rata + " dari 100";
      amb("predikat").textContent = predikatNilai(r.rata);
      var kem = { menyimak: [0, 0], berbicara: [0, 0], membaca: [0, 0], menulis: [0, 0] };
      r.daftar.forEach(function (d) {
        Object.keys(d.hasil.rinci).forEach(function (m) {
          kem[m][0] += d.hasil.rinci[m].nilai; kem[m][1]++;
        });
      });
      var jalur = [];
      Object.keys(kem).forEach(function (m) {
        if (kem[m][1]) jalur.push("<span>" + NAMA_KEMAHIRAN[m] + " " +
          Math.round(kem[m][0] / kem[m][1]) + "</span>");
      });
      amb("rincianNilai").innerHTML = jalur.join("");
      amb("tubuh").innerHTML = "Peserta berasal dari " + (instansi || "\u2026") +
        ". Uji kompetensi diselenggarakan oleh " + (DATA_SRT.penyelenggara || "\u2026") +
        "<br>pada tanggal " + tanggalPanjang(DATA_SRT.tanggal) + ".";
      amb("ttdKiri").textContent = DATA_SRT.pengajar || "";
      amb("namaKiri").textContent = DATA_SRT.pengajar || "";
      amb("jabKiri").textContent = DATA_SRT.jabatan || "";
      amb("ttdKanan").textContent = DATA_SRT.penandatangan || "";
      amb("namaKanan").textContent = DATA_SRT.penandatangan || "";
      amb("jabKanan").textContent = DATA_SRT.jabatan2 || "";
      amb("sandi").textContent = "MyBIPA \u00b7 A2 \u00b7 " + (DATA_SRT.nomor || "");
      skalakanSertifikat();
    };

    daftarUnit.addEventListener("input", function (ev) {
      var inp = ev.target.closest(".ru-timpa");
      if (!inp || !PENGELOLA) return;
      if (inp.value === "") delete NILAI_TIMPA[inp.dataset.unit];
      else NILAI_TIMPA[inp.dataset.unit] = Math.max(0, Math.min(100, parseInt(inp.value, 10) || 0));
      simpanTimpa(); simpanRekap(); segarkanSertifikat();
    });

    tbCetak.addEventListener("click", function () {
      var gaya = document.getElementById("gaya-sertifikat");
      var klon = lembar.cloneNode(true);
      klon.removeAttribute("style"); klon.removeAttribute("id");
      var jendela = window.open("", "_blank");
      if (!jendela) { window.alert("Peramban menghalangi jendela baru. Izinkan jendela sembul untuk mencetak sertifikat."); return; }
      jendela.document.open();
      jendela.document.write(
        '<!DOCTYPE html><html lang="id"><head><meta charset="utf-8">' +
        '<title>Sertifikat \u00b7 ' + (AKUN ? AKUN.nama : "Peserta") + '</title>' +
        '<link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,900' +
        '&family=Plus+Jakarta+Sans:wght@300;400;500;600;700&family=IBM+Plex+Mono:wght@400;600' +
        '&family=Kaushan+Script&display=swap" rel="stylesheet">' +
        '<style>' + (gaya ? gaya.textContent : "") + '</style>' +
        '<style>@page{size:A4 landscape;margin:0}' +
        'html,body{margin:0;padding:0;background:#EDE7DD;display:grid;place-items:center;min-height:100vh}' +
        '.wadah-cetak{width:1122px;height:793px;overflow:hidden}' +
        '.wadah-cetak .srt{transform:scale(.70125);box-shadow:none}' +
        '@media print{body{background:#fff;display:block}}</style></head><body>' +
        '<div class="wadah-cetak">' + klon.outerHTML + '</div>' +
        '<scr' + 'ipt>window.onload=function(){setTimeout(function(){window.focus();window.print();},700);};</scr' + 'ipt>' +
        '</body></html>');
      jendela.document.close();
    });

    setTimeout(function () { segarkanSertifikat(); skalakanSertifikat(); }, 0);
    return bungkus;
  }

  /* ---------- latihan pelafalan dengan pengenal suara ---------- */
  var IZIN_MIKROFON = false;
  function tandaiMikrofon(siap, pesan) {
    Array.prototype.forEach.call(document.querySelectorAll(".mik-tanda"), function (el) {
      el.textContent = pesan;
      el.className = "mik-tanda" + (siap ? " siap" : "");
    });
  }
  function mintaIzinMikrofon(lanjut) {
    if (IZIN_MIKROFON) { lanjut(); return; }
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      IZIN_MIKROFON = true; lanjut(); return;
    }
    tandaiMikrofon(false, "Meminta izin mikrofon\u2026");
    navigator.mediaDevices.getUserMedia({ audio: true }).then(function (arus) {
      IZIN_MIKROFON = true;
      try { arus.getTracks().forEach(function (t) { t.stop(); }); } catch (e) { }
      tandaiMikrofon(true, "Mikrofon siap dipakai");
      lanjut();
    }).catch(function () {
      IZIN_MIKROFON = true;   /* biarkan pengenal suara yang memberi pesan bila memang ditolak */
      tandaiMikrofon(false, "Izin mikrofon belum diberikan");
      lanjut();
    });
  }

  /* Pada peramban yang mendukungnya, keadaan izin diperiksa lebih dahulu sehingga
     pemelajar yang sudah pernah mengizinkan tidak ditanya lagi. */
  function periksaIzinMikrofon() {
    if (!navigator.permissions || !navigator.permissions.query) return;
    try {
      navigator.permissions.query({ name: "microphone" }).then(function (hasil) {
        if (hasil.state === "granted") {
          IZIN_MIKROFON = true;
          tandaiMikrofon(true, "Mikrofon siap dipakai");
        } else if (hasil.state === "denied") {
          tandaiMikrofon(false, "Izin mikrofon diblokir pada peramban");
        }
        hasil.onchange = function () {
          if (hasil.state === "granted") { IZIN_MIKROFON = true; tandaiMikrofon(true, "Mikrofon siap dipakai"); }
        };
      }).catch(function () { });
    } catch (e) { }
  }

  var AdaPengenal = (typeof window !== "undefined") &&
    (window.SpeechRecognition || window.webkitSpeechRecognition);

  function bakuKata(t) {
    return String(t).toLowerCase().replace(/[^a-z\u00e0-\u00ff\s]/g, " ").replace(/\s+/g, " ").trim();
  }
  function jarakKata(a, b) {
    var m = a.length, k = b.length, i, j;
    var d = [];
    for (i = 0; i <= m; i++) { d[i] = [i]; }
    for (j = 0; j <= k; j++) { d[0][j] = j; }
    for (i = 1; i <= m; i++) {
      for (j = 1; j <= k; j++) {
        d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
      }
    }
    return d[m][k];
  }
  function nilaiLafal(sasaran, dengar) {
    var a = bakuKata(sasaran).split(" ").filter(Boolean);
    var b = bakuKata(dengar).split(" ").filter(Boolean);
    if (!b.length) return { nilai: 0, kataSalah: a.slice() };
    var jarak = jarakKata(a, b);
    var nilai = Math.max(0, 1 - jarak / Math.max(a.length, b.length));
    var adaDiDengar = {};
    b.forEach(function (k) { adaDiDengar[k] = true; });
    var salah = a.filter(function (k) {
      if (adaDiDengar[k]) return false;
      return !b.some(function (x) { return jarakKata(k.split(""), x.split("")) <= 1; });
    });
    return { nilai: nilai, kataSalah: salah };
  }

  function buatLafal(b, hal, kunciDasar) {
    var wadah = E("div", "lafal");
    (b.kalimat || []).forEach(function (kal, i) {
      var kunci = kunciDasar + ".lf" + i;
      daftarPoin(hal, kunci); daftarNilai(hal, kunci);
      var kotak = E("div", "lafal-butir");
      kotak.innerHTML = '<p class="lafal-teks"><b>' + (i + 1) + '.</b> \u201C' + kal + '\u201D</p>';
      var aksi = E("div", "lafal-aksi");
      var tb = E("button", "lafal-rekam", "\uD83C\uDFA4 Ucapkan kalimat");
      tb.type = "button";
      var status = E("span", "lafal-status", "");
      var cap = E("span", "lafal-nilai", "belum dinilai");
      aksi.appendChild(tb); aksi.appendChild(cap); aksi.appendChild(status);
      kotak.appendChild(aksi);
      var hasil = E("div", "lafal-dengar");
      kotak.appendChild(hasil);

      function tampilkan(h, terdengar) {
        var mutu = h.nilai >= 0.85 ? "tepat" : (h.nilai >= 0.6 ? "hampir" : "belum");
        kotak.className = "lafal-butir " + mutu;
        cap.className = "lafal-nilai " + mutu;
        cap.textContent = (mutu === "tepat" ? "Pelafalan tepat" :
          mutu === "hampir" ? "Hampir tepat" : "Belum tepat") +
          " \u00b7 " + Math.round(h.nilai * 100);
        var kataDengar = String(terdengar).split(/\s+/).map(function (k) {
          var bersih = bakuKata(k);
          return h.kataSalah.indexOf(bersih) >= 0 ? '<span class="salah">' + k + "</span>" : k;
        }).join(" ");
        hasil.innerHTML = "<b>Terdengar:</b> \u201C" + kataDengar + "\u201D" +
          (h.kataSalah.length ? "<br><b>Perlu diulang:</b> " + h.kataSalah.join(", ") : "");
        JAWAB[kunci] = terdengar; simpan();
        tandaiPoin(hal, kunci);
        setNilai(hal, kunci, h.nilai >= 0.85 ? 1 : (h.nilai >= 0.6 ? 0.6 : h.nilai * 0.5));
      }

      if (!AdaPengenal) {
        tb.disabled = true;
        tb.textContent = "\uD83C\uDFA4 Pengenal suara tidak tersedia";
        status.textContent = "Gunakan Chrome atau Edge, dan buka modul lewat alamat web (https).";
        var tbLatih = E("button", "tbl garis", "Tandai sudah berlatih");
        tbLatih.type = "button";
        tbLatih.addEventListener("click", function () {
          /* tanpa pengenal suara butir ini tidak dapat dinilai, jadi dikeluarkan
             dari perhitungan agar tidak menahan penyelesaian unit */
          if (BUTIR_NILAI[hal]) delete BUTIR_NILAI[hal][kunci];
          tandaiPoin(hal, kunci); JAWAB[kunci] = "berlatih mandiri"; simpan();
          cap.textContent = "sudah berlatih";
          tbLatih.disabled = true;
          perbaruiSemuaNilai();
        });
        aksi.appendChild(tbLatih);
      } else {
        tb.addEventListener("click", function () {
          mintaIzinMikrofon(function () { mulaiDengar(); });
        });
        function mulaiDengar() {
          var Pengenal = window.SpeechRecognition || window.webkitSpeechRecognition;
          var pengenal = new Pengenal();
          pengenal.lang = "id-ID";
          pengenal.interimResults = false;
          pengenal.maxAlternatives = 3;
          tb.classList.add("dengar");
          tb.textContent = "\uD83C\uDFA4 Sedang mendengarkan\u2026";
          tb.disabled = true;
          status.textContent = "Ucapkan kalimat dengan pelan dan jelas.";
          hasil.innerHTML = "";
          var selesai = function () {
            tb.classList.remove("dengar");
            tb.textContent = "\uD83C\uDFA4 Ucapkan lagi";
            tb.disabled = false;
          };
          pengenal.onresult = function (ev) {
            var terbaik = null, nilaiTerbaik = -1;
            for (var i = 0; i < ev.results[0].length; i++) {
              var teks = ev.results[0][i].transcript;
              var h = nilaiLafal(kal, teks);
              if (h.nilai > nilaiTerbaik) { nilaiTerbaik = h.nilai; terbaik = { h: h, teks: teks }; }
            }
            status.textContent = "";
            if (terbaik) tampilkan(terbaik.h, terbaik.teks);
            selesai();
          };
          pengenal.onerror = function (ev) {
            selesai();
            status.textContent = ev.error === "not-allowed"
              ? "Izin mikrofon ditolak. Aktifkan izin mikrofon pada peramban."
              : (ev.error === "no-speech" ? "Suara belum terdengar. Coba lagi."
                : "Pengenal suara gagal: " + ev.error + ".");
          };
          pengenal.onend = selesai;
          try { pengenal.start(); } catch (e) { selesai(); status.textContent = "Tidak dapat memulai perekaman."; }
        }
      }
      wadah.appendChild(kotak);
    });
    var tanda = E("p", "mik-tanda", AdaPengenal
      ? "Tekan tombol mikrofon, lalu izinkan pemakaian mikrofon sekali saja."
      : "Pengenal suara belum tersedia pada peramban ini.");
    wadah.appendChild(tanda);
    wadah.appendChild(E("p", "lafal-catatan",
      "Penilaian membandingkan ucapan Anda dengan kalimat sasaran memakai pengenal suara bahasa " +
      "Indonesia pada peramban. Nilai ini masuk ke kemahiran berbicara pada nilai unit."));
    return wadah;
  }

